package com.example.starter.config;

import java.time.Clock;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时钟配置：业务时间统一取 UTC，测试可替换为可控时钟。
 */
@Configuration
public class TimeConfig {

    /**
     * 生产环境使用 UTC 系统时钟。
     */
    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}
'@, $enc)
[System.IO.File]::WriteAllText("$base\domain\BatchStatus.java", @'
package com.example.starter.domain;

/**
 * 批次状态：OPEN=进行中（可入批、测量、交接），HANDED_OVER=已交接（冻结，禁止重新测量）。
 */
public enum BatchStatus {
    OPEN,
    HANDED_OVER
}
'@, $enc)
[System.IO.File]::WriteAllText("$base\domain\CellStatus.java", @'
package com.example.starter.domain;

/**
 * 电芯状态：ACTIVE=在批参与交接，ISOLATED=已隔离（保留历史，不再参与交接清单）。
 */
public enum CellStatus {
    ACTIVE,
    ISOLATED
}
'@, $enc)
[System.IO.File]::WriteAllText("$base\domain\ReadingStatus.java", @'
package com.example.starter.domain;

/**
 * 读数状态：VALID=有效（可作为终测候选），VOID=已作废（保留记录但不参与终测判定）。
 */
public enum ReadingStatus {
    VALID,
    VOID
}
'@, $enc)
[System.IO.File]::WriteAllText("$base\exception\BusinessException.java", @'
package com.example.starter.exception;

import java.util.List;

/**
 * 业务拒绝异常（HTTP 422）：携带拒绝原因及涉及的电芯编号。
 */
public class BusinessException extends RuntimeException {

    private final List<String> cellCodes;

    public BusinessException(String message) {
        this(message, List.of());
    }

    public BusinessException(String message, List<String> cellCodes) {
        super(message);
        this.cellCodes = cellCodes == null ? List.of() : List.copyOf(cellCodes);
    }

    /**
     * 拒绝涉及的电芯编号列表，无涉及时为空表。
     */
    public List<String> cellCodes() {
        return cellCodes;
    }
}
'@, $enc)
[System.IO.File]::WriteAllText("$base\exception\ConflictException.java", @'
