private <T> T replayOrExecute(String requestId, String type, String hash, Class<T> viewType, Supplier<T> action) {
    var existing = requestLogRepo.findById(requestId);
    if (existing.isPresent()) {
        var log = existing.get();
        if (!log.requestType().equals(type) || !log.requestHash().equals(hash)) throw new ConflictException(...);
        return readValue(log.responseJson(), viewType);
    }
    T result = action.get();
    requestLogRepo.insert(requestId, type, hash, writeValue(result), clock.instant());
    return result;
}
```
